function state(value: string): boolean | null {
  return value === '?' ? null : value === '1';
}
function unpack(data: string): ReadonlyMap<string, IStoredClipFacts> {
  return new Map(
    data.split(' ').map((item) => {
      const [name, ammoType, rack, shots, oneShot, admitted, timeline] =
        item.split('|');
      const facts: IStoredClipFacts = {
        infantryWeapon: true,
        ammoType,
        rackSize: Number(rack),
        clipShots: Number(shots),
        oneShot: oneShot === '1',
        oneShotAmmoAdmitted: state(admitted),
        admissionByYear: timeline.split(',').map((item) => {
          const [year, value] = item.split('~');
          return [Number(year), state(value)] as const;
        }),
      };
      return [name, facts] as const;
    }),
  );
}
/** Callers resolve catalog identity first; ambiguous native aliases stay absent. */
export function getNativeInfantryClipFacts(
  name: string,
  javaClass?: string,
  year?: number,
): INativeInfantryClipFacts | undefined {
  const facts =
    classes.get(javaClass ?? '') ??
    classes.get(native.get(name.toLowerCase().replace(/[^a-z0-9]/g, '')) ?? '');
  if (!facts || year === undefined) return facts;
  if (!Number.isInteger(year) || year < -2147483648 || year > 2147483647)
    return undefined;
  let admitted = facts.oneShotAmmoAdmitted;
  for (const [start, value] of facts.admissionByYear) {
    if (year < start) break;
    admitted = value;
  }
  return { ...facts, oneShotAmmoAdmitted: admitted };
}
